import sys
import heapq
from collections import defaultdict, deque

def shortest_paths_count(V, E, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Step 1: Compute shortest path distances using Dijkstra's Algorithm
    distances = [float('inf')] * V
    distances[s] = 0
    pq = [(0, s)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > distances[u]:
            continue

        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    if distances[t] == float('inf'):
        return 0

    # Step 2: Count number of shortest paths using a BFS-like approach
    path_count = [0] * V
    path_count[s] = 1
    queue = deque([s])

    while queue:
        u = queue.popleft()

        for v, weight in graph[u]:
            if distances[v] == distances[u] + weight:
                if path_count[v] == 0:
                    queue.append(v)
                path_count[v] += path_count[u]

    return path_count[t]

def main():
    input = sys.stdin.readline
    V, E = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(E)]
    s, t = map(int, input().split())

    result = shortest_paths_count(V, E, edges, s, t)
    print(result)

if __name__ == "__main__":
    main()
